<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$q=trim($_GET['q']??'');$params=[];$sql='SELECT lr.*,GROUP_CONCAT(DISTINCT s.skill_name ORDER BY s.skill_name SEPARATOR \' · \') skill_names FROM learning_resources lr LEFT JOIN resource_skills rs ON rs.resource_id=lr.resource_id LEFT JOIN skills s ON s.skill_id=rs.skill_id WHERE lr.is_active=1';if($q!==''){$sql.=' AND (lr.title LIKE ? OR lr.provider LIKE ? OR s.skill_name LIKE ?)';$params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];}$sql.=' GROUP BY lr.resource_id ORDER BY lr.title';$st=$pdo->prepare($sql);$st->execute($params);$resources=$st->fetchAll();$savedStmt=$pdo->prepare('SELECT resource_id FROM saved_resources WHERE user_id=?');$savedStmt->execute([(int)current_user()['user_id']]);$savedResources=array_flip(array_map('intval',$savedStmt->fetchAll(PDO::FETCH_COLUMN)));$pageTitle='Learning resources';$active='resources';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Learn with direction</span><h1 class="h1">Learning resources</h1><p>Find documentation and learning links connected to the skills you want to build.</p></div></div><form class="filters" method="get"><div class="search-box"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Search title, provider or skill…"></div><button class="btn btn-primary btn-sm">Search</button></form><section class="card"><?php foreach($resources as $r):?><div class="resource-row"><div class="resource-icon">▤</div><div style="flex:1"><div class="row-between" style="align-items:flex-start"><div><h3><?=h($r['title'])?></h3><p><?=h($r['provider']?:'Learning resource')?> · <?=h(ucfirst($r['resource_type']))?> · <?= $r['is_free']?'Free / free access available':'Paid or account required'?></p></div><span class="pill pill-green">Curated link</span></div><p style="margin:0 0 7px"><?=h($r['description'])?></p><div class="tag-row"><?php foreach(array_filter(explode(' · ',$r['skill_names']??'')) as $skill):?><span class="tag"><?=h($skill)?></span><?php endforeach;?></div><div style="margin-top:10px"><a class="link-arrow" href="<?=h($r['resource_url'])?>" target="_blank" rel="noopener noreferrer">Open resource ↗</a></div></div></div><?php endforeach;?><?php if(!$resources):?><div class="empty-state"><h2>No matching resources</h2><p>Try another search phrase.</p></div><?php endif;?></section><p class="muted tiny" style="margin-top:13px">Resource links are starter references. Check provider terms, current availability and whether an account is required before recommending them to others.</p></div></main><?php include __DIR__.'/../includes/footer.php';?>
